declare(strict_types=1);$root=dirname(__DIR__);$read=static fn(string $path):string=>(string)file_get_contents($root.'/'.$path);$assert=static function(bool $ok,string $m):void{if(!$ok)throw new RuntimeException($m);};$view=$read('app/Views/admin/crud.php');foreach(['management-form','filter-bar','Limpar filtros','data-view-toggle','management-cards','data-confirm','pagination']as$n)$assert(str_contains($view,$n),'Missing '.$n);$css=$read('public/assets/css/management.css');$assert(str_contains($css,'@media(max-width:520px)'),'Missing mobile rules');$js=$read('public/assets/js/app.js');$assert(str_contains($js,'data-view-toggle'),'Missing card toggle');echo "MANAGEMENT_UI_E2E_OK\n";
